// Build-time image pipeline.
//
// Images live in public/ and are referenced by plain string paths from content
// frontmatter, so they never pass through astro:assets. This script fills that
// gap without moving a single file:
//
//   1. writes a WebP derivative for every raster image into public/_opt/
//   2. records intrinsic dimensions in public/_opt/manifest.json
//
// <Img> then emits a <picture> with the WebP and explicit width/height, which
// is what fixes both page weight and layout shift. Output is gitignored and
// regenerated by `npm run build`; unchanged files are skipped.

import { readdir, stat, mkdir, writeFile, readFile } from 'node:fs/promises';
import path from 'node:path';
import sharp from 'sharp';

const PUBLIC_DIR = path.resolve('public');
const OUT_DIR = path.join(PUBLIC_DIR, '_opt');
const MANIFEST = path.join(OUT_DIR, 'manifest.json');
const EXT = new Set(['.jpg', '.jpeg', '.png']);
const MAX_WIDTH = 1600; // nothing on the site renders wider than this
const QUALITY = 78;

async function* walk(dir) {
  for (const entry of await readdir(dir, { withFileTypes: true })) {
    if (entry.name.startsWith('_opt')) continue;
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) yield* walk(full);
    else yield full;
  }
}

const manifest = await readFile(MANIFEST, 'utf8').then(JSON.parse).catch(() => ({}));

let converted = 0;
let skipped = 0;
let bytesBefore = 0;
let bytesAfter = 0;

for await (const file of walk(PUBLIC_DIR)) {
  if (!EXT.has(path.extname(file).toLowerCase())) continue;

  const rel = '/' + path.relative(PUBLIC_DIR, file).split(path.sep).join('/');
  const outFile = path.join(OUT_DIR, path.relative(PUBLIC_DIR, file)) + '.webp';
  const src = await stat(file);

  const cached = manifest[rel];
  if (cached && cached.mtime === src.mtimeMs) {
    const existing = await stat(outFile).catch(() => null);
    if (existing) {
      skipped++;
      bytesBefore += src.size;
      bytesAfter += existing.size;
      continue;
    }
  }

  try {
    const image = sharp(file, { failOn: 'none' });
    const meta = await image.metadata();
    await mkdir(path.dirname(outFile), { recursive: true });
    const info = await image
      .rotate()
      .resize({ width: Math.min(meta.width ?? MAX_WIDTH, MAX_WIDTH), withoutEnlargement: true })
      .webp({ quality: QUALITY })
      .toFile(outFile);

    manifest[rel] = {
      width: meta.width ?? null,
      height: meta.height ?? null,
      webp: '/_opt' + rel + '.webp',
      webpWidth: info.width,
      webpHeight: info.height,
      mtime: src.mtimeMs,
    };
    converted++;
    bytesBefore += src.size;
    bytesAfter += info.size;
  } catch (err) {
    console.warn(`  ! skipping ${rel}: ${err.message}`);
  }
}

await mkdir(OUT_DIR, { recursive: true });
await writeFile(MANIFEST, JSON.stringify(manifest, null, 0));

const mb = n => (n / 1024 / 1024).toFixed(1) + ' MB';
console.log(
  `images: ${converted} converted, ${skipped} cached — ${mb(bytesBefore)} original vs ${mb(bytesAfter)} webp ` +
  `(${Math.round((1 - bytesAfter / bytesBefore) * 100)}% smaller)`
);
